package dev.tplauncher.companion;
import net.minecraft.client.gui.DrawContext;import net.minecraft.client.gui.screen.Screen;import net.minecraft.client.gui.widget.ButtonWidget;import net.minecraft.client.texture.*;import net.minecraft.text.Text;import net.minecraft.util.Identifier;
import java.nio.file.*;import java.util.*;import java.io.*;import java.awt.Toolkit;import java.awt.datatransfer.*;import javax.imageio.ImageIO;

public final class ScreenshotScreen extends Screen{
 private final Screen parent;private final List<Path> files=new ArrayList<>();private final List<Identifier> textures=new ArrayList<>();private int page;private String message="";
 public ScreenshotScreen(Screen parent){super(Text.literal("Galería F2"));this.parent=parent;}
 @Override protected void init(){clearTextures();files.clear();try(var entries=Files.list(client.runDirectory.toPath().resolve("screenshots"))){entries.filter(p->p.getFileName().toString().toLowerCase(Locale.ROOT).endsWith(".png")&&!Files.isSymbolicLink(p)&&Files.isRegularFile(p)).limit(4096).sorted(Comparator.comparing((Path p)->p.getFileName().toString()).reversed()).forEach(files::add);}catch(IOException ignored){}
  int start=page*6,w=Math.min(190,(width-60)/3),h=Math.min(116,(height-110)/2);for(int i=start;i<Math.min(files.size(),start+6);i++){Path file=files.get(i);int index=i-start,x=width/2-w*3/2+(index%3)*w,y=50+(index/3)*h;Identifier texture=texture(file);textures.add(texture);addDrawableChild(ButtonWidget.builder(Text.literal("Ver captura"),b->client.setScreen(new ImageScreen(this,file))).dimensions(x+4,y+4,w-8,h-8).build());}
  addDrawableChild(ButtonWidget.builder(Text.literal("Anterior"),b->{if(page>0){page--;clearAndInit();}}).dimensions(width/2-160,height-30,90,20).build());addDrawableChild(ButtonWidget.builder(Text.literal("Volver"),b->close()).dimensions(width/2-45,height-30,90,20).build());addDrawableChild(ButtonWidget.builder(Text.literal("Siguiente"),b->{if((page+1)*6<files.size()){page++;clearAndInit();}}).dimensions(width/2+70,height-30,90,20).build());
 }
 private void clearTextures(){if(client!=null)for(Identifier id:textures)if(id!=null)client.getTextureManager().destroyTexture(id);textures.clear();}
 static NativeImage image(Path file)throws Exception{if(Files.size(file)>20*1024*1024)throw new IOException();byte[] bytes=Files.readAllBytes(file);if(bytes.length<24||bytes[0]!=(byte)137||bytes[1]!=80||bytes[2]!=78||bytes[3]!=71)throw new IOException();int w=java.nio.ByteBuffer.wrap(bytes,16,4).getInt(),h=java.nio.ByteBuffer.wrap(bytes,20,4).getInt();if(w<=0||h<=0||w>8192||h>8192||(long)w*h>32000000)throw new IOException();return NativeImage.read(bytes);}
 private Identifier texture(Path file){try(NativeImage original=image(file)){int w=Math.min(512,original.getWidth()),h=Math.max(1,(int)((double)w/original.getWidth()*original.getHeight()));NativeImage small=new NativeImage(w,h,false);original.resizeSubRectTo(0,0,original.getWidth(),original.getHeight(),small);return client.getTextureManager().registerDynamicTexture("tp-f2",new NativeImageBackedTexture(small));}catch(Exception ignored){return null;}}

 @Override public void render(DrawContext c,int mouseX,int mouseY,float delta){TitleAppearance.render(c,width,height);c.drawCenteredTextWithShadow(textRenderer,Text.literal("Galería F2 · "+files.size()+" capturas · "+(page+1)+" / "+Math.max(1,(files.size()+5)/6)),width/2,20,0xEADAF5);super.render(c,mouseX,mouseY,delta);int w=Math.min(190,(width-60)/3),h=Math.min(116,(height-110)/2);for(int i=0;i<textures.size();i++){Identifier id=textures.get(i);if(id!=null)c.drawTexture(id,width/2-w*3/2+(i%3)*w+8,50+(i/3)*h+8,0,0,w-16,h-16,w-16,h-16);}if(files.isEmpty())c.drawCenteredTextWithShadow(textRenderer,Text.literal("Pulsa F2 dentro de una partida para guardar una captura."),width/2,height/2,0xC8B5DA);}
 @Override public void close(){client.setScreen(parent);}
 @Override public void removed(){clearTextures();}
 private static final class ImageScreen extends Screen{
  private final Screen parent;private final Path file;private Identifier texture;private int imageW=16,imageH=9;private String message="";
  ImageScreen(Screen parent,Path file){super(Text.literal(file.getFileName().toString()));this.parent=parent;this.file=file;}
  @Override protected void init(){try{NativeImage image=image(file);imageW=image.getWidth();imageH=image.getHeight();texture=client.getTextureManager().registerDynamicTexture("tp-f2-full",new NativeImageBackedTexture(image));}catch(Exception e){message="No se pudo abrir la captura.";}
   addDrawableChild(ButtonWidget.builder(Text.literal("Copiar imagen"),b->{try{var image=ImageIO.read(file.toFile());Toolkit.getDefaultToolkit().getSystemClipboard().setContents(new Transferable(){public DataFlavor[] getTransferDataFlavors(){return new DataFlavor[]{DataFlavor.imageFlavor};}public boolean isDataFlavorSupported(DataFlavor flavor){return flavor.equals(DataFlavor.imageFlavor);}public Object getTransferData(DataFlavor flavor)throws UnsupportedFlavorException{if(!isDataFlavorSupported(flavor))throw new UnsupportedFlavorException(flavor);return image;}},null);message="Imagen copiada.";}catch(Exception e){message="El portapapeles no está disponible.";}}).dimensions(width/2-170,height-30,105,20).build());
   addDrawableChild(ButtonWidget.builder(Text.literal("Usar de fondo"),b->{try{Path target=TitleAppearance.backgroundPath();Files.createDirectories(target.getParent());Files.copy(file,target,StandardCopyOption.REPLACE_EXISTING);message="Fondo guardado.";}catch(Exception e){message="No se pudo guardar el fondo.";}}).dimensions(width/2-55,height-30,105,20).build());addDrawableChild(ButtonWidget.builder(Text.literal("Volver"),b->close()).dimensions(width/2+60,height-30,105,20).build());
  }
  @Override public void render(DrawContext c,int x,int y,float delta){c.fill(0,0,width,height,0xFF08080D);if(texture!=null){double scale=Math.min((width-30.)/imageW,(height-85.)/imageH);int w=(int)(imageW*scale),h=(int)(imageH*scale);c.drawTexture(texture,(width-w)/2,(height-55-h)/2,0,0,w,h,w,h);}c.drawCenteredTextWithShadow(textRenderer,Text.literal(message),width/2,height-45,0xD1B2EA);super.render(c,x,y,delta);}
  @Override public void close(){client.setScreen(parent);}@Override public void removed(){if(texture!=null){client.getTextureManager().destroyTexture(texture);texture=null;}}
 }
}
